import{_ as a,o as _,a as e,b as d}from"./app.DII24pJb.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"随路量化","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"}],"lastUpdated":1789956443000}'),o={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/accompanying_quantization.md"};function n(r,t,i,l,c,s){return _(),e("div",null,[...t[0]||(t[0]=[d(`<div><article class="markdown-body"><h1>随路量化</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵搬出支持Cast和带系数的量化。</p><p>使用<code>asc_quant_mode::F322F16</code>或<code>asc_quant_mode::F322BF16</code>将float转换成half/bfloat16_t，无需量化系数，舍入模式采用CAST_RINT。</p><p>带参数量化包括两种粒度：</p><ul><li>Scalar：整个C矩阵共享一个量化参数。</li><li>Tensor/Vector：C矩阵每一列对应一个8B量化参数，参数shape为[N]。先用<a href="../asc_copy_l12fb/asc_copy_l12fb.html">asc_copy_l12fb</a>从L1 Buffer搬入量化区，再设置起始地址索引。量化地址索引为量化区字节地址除以128，不是元素下标；激活地址索引为激活区字节地址除以64。两个参数区分别寻址，起始地址与长度都不能超过对应区域。</li></ul><div data-filter="950"><p>针对Ascend 950PR&amp;950DT系列产品产品，Scalar系数使用<a href="../asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant(scale, offset, is_signed)</a>配置，Vector地址使用<a href="../asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>配置。搬出调用的<code>quant_pre_mode</code>使用<code>asc_quant_mode</code>枚举。</p></div><div data-filter="910b,A3"><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3系列产品</p></div><div data-filter="910b"><p>Atlas A2系列产品</p></div><p>Scalar系数通过<a href="../asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a>传入打包后的<code>uint64_t config</code>，低32位必须是float的位模式，不能将浮点数数值转换成uint64_t；Vector地址使用<a href="../asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a>配置。搬出调用的<code>quant_pre</code>使用整数，可显式转换<code>asc_quant_mode</code>枚举得到模式编码。</p></div><p>配置系数只写寄存器，不会自动选择搬出模式。下文模式名称均为<code>asc_quant_mode</code>的成员，调用时须按所选重载的参数类型传入。</p><p>当前支持的量化模式及其功能描述如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>DEQF16,                // DeQuant_Float16：int32_t反量化成half，scalar量化
VDEQF16,               // Vector_DeQuant_Float16：int32_t反量化成half，tensor量化
QF322B8_PRE,           // Quant_Float32_2_B8：float量化成int8_t/uint8_t，scalar量化
VQF322B8_PRE,          // Vector_Quant_Float32_2_B8：float量化成int8_t/uint8_t，tensor量化
REQ8,                  // ReQuant_int8：int32_t重量化成int8_t/uint8_t，scalar量化
VREQ8,                 // Vector_ReQuant_int8：int32_t重量化成int8_t/uint8_t，tensor量化
</code></pre></div><div data-filter="950"><p>除上述量化模式外，Ascend 950PR&amp;950DT系列产品产品还额外支持以下量化模式：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>QF322FP8_PRE,          // Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，scalar量化
VQF322FP8_PRE,         // Vector_Quant_Float32_2_FP8: float量化成fp8_e4m3fn_t，tensor量化
QF322HIF8_PRE,         // Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，scalar量化
VQF322HIF8_PRE,        // Vector_Quant_Float32_2_HIF8: float量化成hifloat8_t(Half to Away Round)，tensor量化
QF322HIF8_PRE_HYBRID,  // Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，scalar量化
VQF322HIF8_PRE_HYBRID, // Vector_Quant_Float32_2_HIF8_Hybrid: float量化成hifloat8_t(Hybrid Round)，tensor量化
QS322BF16_PRE,         // Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，scalar量化
VQS322BF16_PRE,        // Vector_Quant_Int32_2_BFloat16: int32_t量化成bfloat16_t，tensor量化
QF322F16_PRE,          // Quant_Float32_2_Float16: float量化成half，scalar量化
VQF322F16_PRE,         // Vector_Quant_Float32_2_Float16: float量化成half，tensor量化
QF322BF16_PRE,         // Quant_Float32_2_BFloat16: float量化成bfloat16_t，scalar量化
VQF322BF16_PRE,        // Vector_Quant_Float32_2_BFloat16: float量化成bfloat16_t，tensor量化
QF322F32_PRE,          // Quant_Float32_2_Float32: float量化成float，scalar量化，使用有限精度的量化系数，需按输入范围验证误差
VQF322F32_PRE,         // Vector_Quant_Float32_2_Float32: float量化成float，tensor量化，使用有限精度的量化系数，需按输入范围验证误差
</code></pre></div></div><p>不同量化模式的量化算法详细介绍参见<a href="accompanying_quantization_and_relu_scenario_combination.html">随路量化与随路ReLU场景组合</a>。</p><p>量化参数比特位含义见下表：</p><div data-filter="A3,910b"><p><strong>表1</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>0~31</td><td>M1</td><td>32位数视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>32~35</td><td>N</td><td>4位比特位，表示范围为[1, 16]（b&#39;0000对应表示1，b&#39;1111对应表示16）。<br>当模式为(V)REQ8时，MCB标志位置为1时，将输入的值进行右移N比特位。当模式为(V)QF322B8_PRE，N为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>36</td><td>MCB标志位</td><td>Mode Control Bit。如果置为0，输入的int32_t会被直接转换为float，N为无效值。如果置为1，输入的int32_t会先右移N比特位，转变成int16_t，然后转换为float。当模式为(V)QF322B8_PRE时，此标志位为无效比特。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>37~45</td><td>Offset</td><td>9bit的整型数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。<br>当模式为(V)DEQF16时，此变量为无效变量。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div><div data-filter="950"><p><strong>表2</strong> 量化参数QUANT_PRE比特位含义映射表（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>模式</th><th>比特位数</th><th>变量名</th><th>作用介绍</th></tr></thead><tbody><tr><td>•(V)REQ8<br>•(V)QF322B8_PRE<br>•(V)DEQF16<br>•(V)QF322FP8_PRE<br>•(V)QF322HIF8_PRE<br>•(V)QF322HIF8_PRE_HYBRID<br>•(V)QS322BF16_PRE<br>•(V)QF322F16_PRE<br>•(V)QF322BF16_PRE<br>•(V)QF322F32_PRE<br>•(V)REQ4<br>•(V)QF322S4_PRE</td><td>0~12</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>13~31</td><td>M1</td><td>数据类型视为float，硬件以(1, 8, 10)的格式，即1个符号位、8个指数位和10个尾数位作为量化计算所需要乘的值。其中31位为符号位，23~30位为指数位，13~22位为尾数位。其值不能为inf/nan。</td></tr><tr><td>同第一行</td><td>32~36</td><td>-</td><td>无效比特位，用户无需关注。</td></tr><tr><td>同第一行</td><td>37~45</td><td>Offset</td><td>9bit整形数据，源数据乘以量化系数或者随路系数的计算结果，可以与Offset表示的整数值进行相加。若不使用offset，请置为0。当模式为(V)REQ8、(V)QF322B8_PRE、(V)REQ4、(V)QF322S4_PRE时该变量生效。</td></tr><tr><td>同第一行</td><td>46</td><td>Sign标志位</td><td>如果置为1，表明量化结果是signed(int8)；如果为置为0，表明量化结果是unsigned(uint8)。仅在(V)REQ8、(V)QF322B8_PRE中会用到。</td></tr><tr><td>同第一行</td><td>47~63</td><td>-</td><td>无效比特位，用户无需关注。</td></tr></tbody></table></div></article></div>`,1)])])}const f=a(o,[["render",n]]);export{F as __pageData,f as default};
